"Set aside time for silent prayer, meditation, or a Holy Hour, with a gentle bell to begin and end.": "Prenez du temps pour la prière silencieuse, la méditation ou une heure sainte, avec une cloche douce au début et à la fin.",
"Test what you know about the saints, Scripture, Church history, and great Catholic books.": "Testez vos connaissances sur les saints, l’Écriture, l’histoire de l’Église et les grands livres catholiques.",
"Every prayer as an illustrated prayer card. Choose a topic, then open a card to pray it, save it, or print it.": "Chaque prière sous forme d’image illustrée. Choisissez un thème, puis ouvrez une image pour la prier, l’enregistrer ou l’imprimer.",
"The prayer St. Ignatius never wanted his companions to skip: five short steps to look back on the day with God.": "La prière que saint Ignace ne voulait jamais voir omise par ses compagnons : cinq courtes étapes pour relire la journée avec Dieu.",
"Gregorian chant and beloved Catholic hymns, with recordings and the words in Latin and English: the Salve Regina, Pange Lingua, Veni Creator, Adeste Fideles, and more.": "Chant grégorien et cantiques catholiques bien-aimés, avec enregistrements et paroles en latin et en anglais : le Salve Regina, le Pange Lingua, le Veni Creator, l’Adeste Fideles et d’autres.",
"The Hours of Our Lady, from Matins to Compline, following the seasons of the year. A beloved prayer of religious, tertiaries, and those who wear the Brown Scapular.": "Les Heures de Notre Dame, des Matines aux Complies, au fil des temps de l’année. Une prière chère aux religieux, aux tertiaires et à ceux qui portent le scapulaire brun.",
"The Brown and Green Scapulars, the Miraculous and St. Benedict Medals, First Fridays and First Saturdays, and holy water: what each one is, how to keep it, and its prayers.": "Les scapulaires brun et vert, la Médaille miraculeuse et la médaille de saint Benoît, les premiers vendredis et premiers samedis, et l’eau bénite : ce qu’est chacun, comment le vivre, et ses prières.",
"The ancient prayer of the Incarnation, prayed at morning, noon, and evening. During the Easter season, the Regina Caeli.": "L’antique prière de l’Incarnation, priée le matin, à midi et le soir. Au temps pascal, le Regina Caeli.",
"Pray with a passage of Scripture the way the monks did: read, reflect, respond, and rest in God.": "Priez avec un passage de l’Écriture comme le faisaient les moines : lire, méditer, répondre et se reposer en Dieu.",
"Keep a private record of your daily prayer, build a steady habit, and see your faithfulness over the weeks.": "Tenez un suivi privé de votre prière quotidienne, prenez une habitude régulière et voyez votre fidélité au fil des semaines.",
"Every part of the Mass in order, with when to stand, sit, and kneel, and what each moment means. Follow along on your phone at Mass.": "Chaque partie de la messe dans l’ordre, avec quand se lever, s’asseoir et se mettre à genoux, et le sens de chaque moment. Suivez-la sur votre téléphone pendant la messe.",
"Every pope from St. Peter to Leo XIV, century by century.": "Tous les papes, de saint Pierre à Léon XIV, siècle après siècle.",
"The great religious orders of the Church: monks, canons, friars, clerks regular, sisters, and the military orders of the crusades.": "Les grands ordres religieux de l’Église : moines, chanoines, frères, clercs réguliers, sœurs, et les ordres militaires des croisades.",
"The most famous icons of East and West, what they show, and the stories behind them.": "Les icônes les plus célèbres d’Orient et d’Occident, ce qu’elles montrent et leur histoire.",
"The twenty-three Eastern Catholic Churches, in full communion with Rome: their traditions, leaders, and lands.": "Les vingt-trois Églises catholiques orientales, en pleine communion avec Rome : leurs traditions, leurs pasteurs et leurs terres.",
"How to become Catholic or come home, the basics of everyday Catholic life, and guides to discerning and living each vocation: marriage, priesthood, religious life, and more.": "Comment devenir catholique ou revenir à l’Église, les bases de la vie catholique au quotidien, et des guides pour discerner et vivre chaque vocation : mariage, sacerdoce, vie religieuse et d’autres.",
"The lists every Catholic learns, explained: the Ten Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more.": "Les listes que tout catholique apprend, expliquées : les dix commandements, les Béatitudes, les commandements de l’Église, les sacrements, les vertus, les œuvres de miséricorde, les péchés capitaux et d’autres.",
"A walk through a Catholic church: what each part is for, the sacred vessels, the vestments, the colors of the seasons, and how to take part in the Mass.": "Une visite d’une église catholique : à quoi sert chaque partie, les vases sacrés, les vêtements liturgiques, les couleurs des temps et comment participer à la messe.",
"All twenty-one ecumenical councils, from Nicaea to Vatican II: when and where they met, and what each one taught.": "Les vingt et un conciles œcuméniques, de Nicée à Vatican II : quand et où ils se sont réunis, et ce que chacun a enseigné.",
"Clear, short definitions of the words of the Catholic faith, from Absolution to the Vulgate.": "Des définitions claires et courtes des mots de la foi catholique, d’« absolution » à « Vulgate ».",
"The words of the saints, from the Church Fathers to our own day, each with its source. Search them, browse by theme, and share your favorites.": "Les paroles des saints, des Pères de l’Église à nos jours, chacune avec sa source. Cherchez-les, parcourez-les par thème et partagez vos préférées.",
"Pick as many answers as you like: your name, your work, your needs, and what you love in a saint. Sanctify suggests friends in heaven who fit.": "Choisissez autant de réponses que vous voulez : votre prénom, votre travail, vos besoins et ce que vous aimez chez un saint. Sanctify vous propose des amis au ciel qui vous ressemblent.",
