"Browse the saints →": "Parcourir les saints →",
"Pick your work, your needs, your name, and what you love in a saint to find friends in heaven.": "Choisissez votre travail, vos besoins, votre prénom et ce que vous aimez chez un saint pour trouver des amis au ciel.",
"Choose as many as you like": "Choisissez-en autant que vous voulez",
