"Catholic Letters": "Lettres catholiques",
"{n} of these books can be read right here": "{n} de ces livres peuvent être lus ici même",
", in public-domain editions, one short section at a time. Look for the “Read on Sanctify” mark.": ", dans des éditions du domaine public (en anglais), une courte section à la fois. Cherchez la mention « Lire sur Sanctify ».",
