"The New Testament": "Le Nouveau Testament",
"From Matthew to Revelation in three months.": "De Matthieu à l’Apocalypse en trois mois.",
"The Whole Bible in a Year": "Toute la Bible en un an",
"All 73 books of the Catholic Bible, about four chapters a day.": "Les 73 livres de la Bible catholique, environ quatre chapitres par jour.",
"The core teachings of the Catholic faith, each with the Scripture passages and Catechism paragraphs behind it, the witness of the Church Fathers, and charitable answers to the objections Catholics most often hear.": "Les enseignements essentiels de la foi catholique, chacun avec les passages de l’Écriture et les paragraphes du Catéchisme qui le fondent, le témoignage des Pères de l’Église et des réponses charitables aux objections que les catholiques entendent le plus souvent.",
