"Prayer badges count the days you mark in your prayer tracker; finishing a Rosary, chaplet, or other guided prayer marks it for you.": "Les badges de prière comptent les jours cochés dans votre suivi de prière ; terminer un Rosaire, un chapelet ou une autre prière guidée le coche pour vous.",
